begin;
select no_plan();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
create function pg_temp.pending_fixture(n integer,short_subject boolean default true) returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';c uuid;
begin
 c:=public.save_campaign(t,null,0,jsonb_build_object('title','Synthetic evidence '||n,'goal','Original educational note','channel','email_text','planned_at',date_trunc('milliseconds',now()+interval '100 days'+n*interval '2 days'),'audience_id','00000000-0000-4000-8000-000000000502'));
 update public.campaigns set synthetic=true where id=c;
 perform public.approve_calendar(t,c,1);
 perform public.save_copy(t,c,1,jsonb_build_object('subject',case when short_subject then 'A considered note' else 'A closer look at the original details, considered at your own pace' end,'preheader','Original fixture','body','An original educational note for this fictional studio.','cta','Explore','url','https://north-studio.example/collection'));return c;
end $$;
create function pg_temp.ready_render(c uuid) returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';j public.job_runs;row public.campaigns;r uuid;p uuid;
begin
 select * into row from public.campaigns where id=c;
 perform public.enqueue_render(t,c,row.copy_revision,row.design_revision);
 select * into j from public.claim_job(t);
 r:=public.finish_render_job(j.id,j.lease_token,'{"synthetic":true,"strips":[]}');
 select * into row from public.campaigns where id=c;
 perform public.review_render(t,r,row.design_revision,'approved','whole_design','Owner exact fixture approval');
 select * into row from public.campaigns where id=c;
 p:=public.create_delivery_package(t,c,row.delivery_revision,'{"senderName":"Synthetic North","senderEmail":"studio@north-studio.example","address":"42 Fictional Road, Synthetic Town","unsubscribeUrl":"https://north-studio.example/unsubscribe","privacyUrl":"https://north-studio.example/privacy"}');return p;
end $$;
create function pg_temp.sent_fixture(n integer,short_subject boolean) returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';c uuid;p uuid;j public.job_runs;f public.fixture_deliveries;
begin
 c:=pg_temp.pending_fixture(n,short_subject);perform public.approve_copy(t,c,2);p:=pg_temp.ready_render(c);
 if not exists(select 1 from public.campaign_send_metadata where package_id=p) then raise exception 'Pre-send metadata missing';end if;
 perform public.enqueue_delivery(t,p,(select revision from public.delivery_packages where id=p));select * into j from public.claim_job(t);
 perform public.fixture_delivery_command(j.id,j.lease_token,'reconcile');perform public.fixture_delivery_command(j.id,j.lease_token,'prepare');perform public.fixture_delivery_command(j.id,j.lease_token,'schedule');perform public.finish_delivery_job(j.id,j.lease_token);
 select * into f from public.fixture_deliveries where package_id=p;
 perform public.confirm_fixture_sent(t,f.id,f.scheduled_at);return f.id;
end $$;
create function pg_temp.run_reports() returns void language plpgsql as $$
declare j public.job_runs;x jsonb;n integer:=0;
begin
 loop select * into j from public.claim_job('00000000-0000-4000-8000-000000000102');exit when j.id is null;
 if j.kind='results.pull' then x:=public.fixture_result_payload(j.id,j.lease_token,(j.input->>'deliveryId')::uuid,j.input->>'window');perform public.finish_result_job(j.id,j.lease_token,x);
 elsif j.kind='reports.digest' then perform public.finish_result_digest(j.id,j.lease_token);
 elsif j.kind='learning.synthesize' then perform public.finish_learning_job(j.id,j.lease_token);
 else raise exception 'Unexpected test job %',j.kind;end if;n:=n+1;if n>100 then raise exception 'Queue failed to drain';end if;end loop;
end $$;
do $$begin for i in 1..8 loop perform pg_temp.sent_fixture(i,i%2=1);end loop;end $$;
select is((select count(*) from public.campaign_send_metadata),8::bigint,'metadata persisted before every provider operation');
select is((select count(*) from public.job_runs where kind='results.pull'),16::bigint,'each confirmed send queues exactly two result windows');
select is((select consecutive_sends from public.autopilot_streaks where tenant_id='00000000-0000-4000-8000-000000000102'),8,'eight confirmed sends form consecutive streak');
select public.save_l2_simulation_policy('00000000-0000-4000-8000-000000000102',0,true,10);
select set_config('test.pending',pg_temp.pending_fixture(30)::text,true);
select throws_ok($$select public.prepare_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid,2)$$,'23514',null,'fewer than ten sends cannot enter default L2 simulation');
select public.advance_results_clock('00000000-0000-4000-8000-000000000102',now()+interval '200 days');
select set_config('test.pull',(select id::text from public.claim_job('00000000-0000-4000-8000-000000000102')),true);
select set_config('test.lease',(select lease_token::text from public.job_runs where id=current_setting('test.pull')::uuid),true);
select throws_ok($$select public.fixture_result_payload(current_setting('test.pull')::uuid,gen_random_uuid(),(select (input->>'deliveryId')::uuid from public.job_runs where id=current_setting('test.pull')::uuid),'48h')$$,'PT409',null,'wrong result lease cannot read fixture provider context');
select throws_ok($$select public.finish_result_job(current_setting('test.pull')::uuid,current_setting('test.lease')::uuid,'{"source":"provider","revenueMinor":999999}')$$,'23514',null,'caller cannot forge fixture source or revenue');
select public.finish_result_job(current_setting('test.pull')::uuid,current_setting('test.lease')::uuid,public.fixture_result_payload(current_setting('test.pull')::uuid,current_setting('test.lease')::uuid,(select (input->>'deliveryId')::uuid from public.job_runs where id=current_setting('test.pull')::uuid),(select input->>'window' from public.job_runs where id=current_setting('test.pull')::uuid)));
select pg_temp.run_reports();
select is((select count(*) from public.campaign_results),16::bigint,'48-hour and seven-day pulls persist actual provider window payloads');
select ok(not exists(select 1 from public.campaign_results where collected_at<window_end or source<>'fixture'),'window maturity/source retained');
select public.enqueue_learning('00000000-0000-4000-8000-000000000102');select pg_temp.run_reports();
select is((select count(*) from public.learned_rules),0::bigint,'four per side produces no influential or proposed rule');
select is((select status from public.learning_runs order by created_at desc limit 1),'insufficient','insufficient run explanation persists');
select set_config('test.f9',pg_temp.sent_fixture(9,true)::text,true);select set_config('test.f10',pg_temp.sent_fixture(10,false)::text,true);
select is((select consecutive_sends from public.autopilot_streaks where tenant_id='00000000-0000-4000-8000-000000000102'),10,'ten consecutive rejection-free confirmed sends reach eligibility');
select public.confirm_fixture_sent('00000000-0000-4000-8000-000000000102',current_setting('test.f10')::uuid,now()+interval '200 days');
select is((select consecutive_sends from public.autopilot_streaks where tenant_id='00000000-0000-4000-8000-000000000102'),10,'send replay never increments eligibility twice');
select set_config('test.partial',pg_temp.sent_fixture(11,true)::text,true);select public.set_fixture_metrics('00000000-0000-4000-8000-000000000102',current_setting('test.partial')::uuid,'partial');
select set_config('test.incomparable',pg_temp.sent_fixture(12,false)::text,true);select public.set_fixture_metrics('00000000-0000-4000-8000-000000000102',current_setting('test.incomparable')::uuid,'incomparable');
select public.advance_results_clock('00000000-0000-4000-8000-000000000102',now()+interval '200 days');select pg_temp.run_reports();
select is((select count(*) from public.result_digests),1::bigint,'daily digest idempotency is tenant local date');
select is((select count(*) from public.campaign_results where not complete),2::bigint,'partial windows remain explicitly incomplete');
select throws_ok($$select public.set_fixture_metrics('00000000-0000-4000-8000-000000000102',current_setting('test.partial')::uuid,'complete')$$,'23514',null,'metrics cannot silently rewrite immutable partial history');
select public.enqueue_learning('00000000-0000-4000-8000-000000000102');select pg_temp.run_reports();
select is((select count(*) from public.learned_rules),1::bigint,'five complete comparable campaigns per side produces one advisory rule');
select is((select (evidence->>'shortCount')::integer from public.learned_rules),5,'partial short sample excluded');
select is((select (evidence->>'detailedCount')::integer from public.learned_rules),5,'incomparable detailed sample excluded');
select set_config('test.rule',(select id::text from public.learned_rules),true);
select is(public.fixture_copy_preference('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid),'{}'::jsonb,'proposed rule has no generation influence');
select public.review_learned_rule('00000000-0000-4000-8000-000000000102',current_setting('test.rule')::uuid,1,'pinned');
select is(public.fixture_copy_preference('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid)->>'preferredGroup','short','explicitly pinned matching own rule guides fixture preference');
select public.review_learned_rule('00000000-0000-4000-8000-000000000102',current_setting('test.rule')::uuid,2,'dismissed');
select is(public.fixture_copy_preference('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid),'{}'::jsonb,'dismissed rule has no influence');
-- Force a new leased synthesis over the same immutable evidence, without using an already-completed idempotency key.
insert into public.job_runs(tenant_id,kind,idempotency_key,input,created_by) values('00000000-0000-4000-8000-000000000102','learning.synthesize','test:repeat-learning','{}','00000000-0000-4000-8000-000000000004');select pg_temp.run_reports();
select is((select status from public.learned_rules where id=current_setting('test.rule')::uuid),'dismissed','repeat synthesis never reactivates dismissed evidence');
select set_config('test.candidate',public.prepare_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid,2)::text,true);
select throws_ok($$select public.simulate_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.candidate')::uuid,now()+interval '71 hours')$$,'23514',null,'71 hours cannot approve silence');
select public.save_copy('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid,2,'{"subject":"A revised note","preheader":"Fixture","body":"An original revised educational note.","cta":"Explore","url":"https://north-studio.example/collection"}');
select throws_ok($$select public.simulate_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.candidate')::uuid,now()+interval '72 hours')$$,'PT409',null,'copy edit invalidates exact silence candidate');
select set_config('test.candidate',public.prepare_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid,3)::text,true);
select lives_ok($$select public.simulate_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.candidate')::uuid,now()+interval '72 hours')$$,'frozen 72-hour clock approves exact validated copy');
select is((select design_state from public.campaigns where id=current_setting('test.pending')::uuid),'unassigned','L2 silence does not approve design');
select throws_ok($$select public.create_delivery_package('00000000-0000-4000-8000-000000000102',current_setting('test.pending')::uuid,(select delivery_revision from public.campaigns where id=current_setting('test.pending')::uuid),'{}')$$,'23514',null,'silence cannot package unreviewed design');
select set_config('test.pkg',pg_temp.ready_render(current_setting('test.pending')::uuid)::text,true);
select lives_ok($$select public.simulate_l2_schedule('00000000-0000-4000-8000-000000000102',current_setting('test.candidate')::uuid,current_setting('test.pkg')::uuid,(select revision from public.delivery_packages where id=current_setting('test.pkg')::uuid))$$,'L2 fixture scheduling uses exact owner-approved package domain command');
select is((select delivery_state from public.campaigns where id=current_setting('test.pending')::uuid),'queued','simulation queues intent rather than claiming provider sent');
select ok(not exists(select 1 from public.l2_simulation_policies where production_enabled or design_delegation),'production L2 and design delegation remain constrained off');
select set_config('test.reject',pg_temp.pending_fixture(40)::text,true);
select public.reject_campaign_version('00000000-0000-4000-8000-000000000102',current_setting('test.reject')::uuid,'copy',2,'Owner rejects this synthetic version','single','');
select is((select consecutive_sends from public.autopilot_streaks where tenant_id='00000000-0000-4000-8000-000000000102'),0,'owner rejection resets conservative consecutive streak');
select throws_ok($$select public.simulate_l2_silence('00000000-0000-4000-8000-000000000102',current_setting('test.candidate')::uuid,now()+interval '72 hours')$$,'PT409',null,'rejection generation invalidates previous simulation');
select public.review_learned_rule('00000000-0000-4000-8000-000000000102',current_setting('test.rule')::uuid,3,'pinned');
select set_config('test.hard',pg_temp.pending_fixture(60)::text,true);
select public.reject_campaign_version('00000000-0000-4000-8000-000000000102',current_setting('test.reject')::uuid,'copy',2,'Explicit owner phrase prohibition wins','audience','considered');
select is(public.fixture_copy_preference('00000000-0000-4000-8000-000000000102',current_setting('test.hard')::uuid)->>'preferredGroup','short','pinned preference still exists as advisory evidence');
select throws_ok($$select public.approve_copy('00000000-0000-4000-8000-000000000102',current_setting('test.hard')::uuid,2)$$,'23514',null,'hard owner prohibition blocks preferred learned subject');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.campaign_results),0::bigint,'foreign owner cannot read results');
select throws_ok($$select public.advance_results_clock('00000000-0000-4000-8000-000000000102',now()+interval '200 days')$$,'42501',null,'foreign owner cannot mutate reporting');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select is((select count(*) from public.campaign_results),0::bigint,'staff cannot read revenue');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.campaign_results),0::bigint,'designer cannot read revenue');
select is((select count(*) from public.learned_rules),0::bigint,'designer cannot read private learning');
select throws_ok($$select public.save_l2_simulation_policy('00000000-0000-4000-8000-000000000102',1,true,1)$$,'42501',null,'designer cannot set autopilot policy');
select * from finish();rollback;
